def old_0021_reconcile_seed_acceptances(apps, schema_editor):
    Offer = apps.get_model('storefront', 'Offer')
    allowed = ['seller@flatfair.sg', 'buyer@flatfair.sg'] + [f'seller{i}@demo.flatfair.sg' for i in range(1, 7)]
    seen = set()
    for offer in Offer.objects.filter(status='accepted', buyer__username__in=allowed, listing__seller__username__in=allowed).exclude(seedKey__isnull=True).order_by('pk'):
        if offer.listing_id in seen:
            Offer.objects.filter(pk=offer.pk).update(status='declined')
        else:
            seen.add(offer.listing_id)


def old_0023_fill_public_ids(apps, schema_editor):
    Listing = apps.get_model('storefront', 'Listing')
    listings = Listing.objects.using(schema_editor.connection.alias)
    for pk in listings.filter(publicId__isnull=True).values_list('pk', flat=True).iterator():
        listings.filter(pk=pk).update(publicId=uuid.uuid4())


old_0026_SALES = Path(__file__).resolve().parents[2] / 'assets' / 'ml' / 'recent_sales.csv.gz'


def old_0026_loadSales(apps, schema_editor):
    Sale = apps.get_model('storefront', 'Sale')
    if not old_0026_SALES.exists():
        return
    with gzip.open(old_0026_SALES, 'rt', newline='') as f:
        rows = [Sale(month=date.fromisoformat(row['month'] + '-01'), town=row['town'], flatType=row['flat_type'], block=row['block'], street=row['street_name'], storeyRange=row['storey_range'], floorAreaSqm=float(row['floor_area_sqm']), flatModel=row['flat_model'], leaseCommenceYear=int(row['lease_commence_date']), price=int(float(row['resale_price']))) for row in csv.DictReader(f)]
    Sale.objects.bulk_create(rows, batch_size=2000)


